# Base class for PageObjects
# Common low level interactions with the UI exist here.
# Application context switching is handled here using a Python decorator to
# reduce boilerplate code.
#  see @ApplicationManager
#  see @app_ctx_function
#
# PageObjects can inherit from this class:
#
# e.g. class MyPageObject(BaseUIPageObject):


import logging
import interops.libraries.desktop.decorators as deco
from interops.libraries.desktop.application import ApplicationManager
import squishtest3 as sq

logger = logging.getLogger(__name__)


class BaseUIPageObject(object):
#     A Base object for Page Objects interacting with the UI via Squish API.
#
#     This Base class provides context switching and UI interaction functions
#     that are typically common to all PageObjects.
#
#     Attributes:
#         application_name (str): Name of application this Page Object maps to.
#
#
    application_name = None
    application_host = None
    application_port = None

    #ToT=Yes
    def __init__(self):
        pass

    def set_application_name(self, applicationName):
        self.application_name = applicationName

    def set_application_host(self, host):
        self.application_host = host

    def set_application_port(self, port):
        self.application_port = port

    def use_application(self):
#         Changes Application Context to the application relevant to this Page Object.
#
#         Calls ApplicationManager to start or switch to this Page Object's application.
#         Host and port can be specified within the application_name using the format
#         application_name:host:port
#         or specified as separate values within the class attributes.
#
#         Only application_name is required, host and port are optional.
#
#         Args:
#            No arguments.
#
#         Returns:
#             No return value.
#

        #logger.debug(self.application_name)
        if self.application_name=="none" : return

        if ":" in str(self.application_name) and len(str(self.application_name).split(':')) >1:
            #aut:host:port
            tokens = str(self.application_name).split(':')
            aut = tokens[0]
            host = tokens[1]
            port = tokens[2] if len(tokens) >=3 else None
            logger.debug("Calling app mgr with " + aut + " " + host + " " + str(port))
            ApplicationManager.use_application_context(aut, host, port)
        else:
            #Use object fields
            ApplicationManager.use_application_context(self.application_name, self.application_host, self.application_port)

    @deco.app_ctx_function()
    def mouseClick(self,target):
        try:
            logger.debug("mouseClick target: " + str(target))
            sq.mouseClick(sq.waitForObject(target), 24, 11, sq.MouseButton.PrimaryButton)
        except Exception as e:
            logger.info("Mouse Click failed :-"+str(e))


    @deco.app_ctx_function()
    def waitForObject(self,target):
        try:
            sq.waitForObjectExists(target)
        except:
            logging.warning('Failed to find object [' + str(target) + ']')


    @deco.app_ctx_function()
    def click_button(self, target):
        logger.debug("click_button target: " + str(target))
        sq.clickButton(sq.waitForObject(target))

    @deco.app_ctx_function()
    def type(self, target, value):
        logger.debug("type target: " + str(target))

        sq.type(sq.waitForObject(target), value)


    def show(self):

#         Activates and displays the window the top window of this application.
#
#         If the window is minimized or maximized, this method will restores it to its original size and position.
#         This is useful in situations where a window has been unintentionally hidden by a user and Squish can't interact with it.
#         e.g FKPID UI has been hidden and Squish can't interact.



        this_ctx = None
        logger.debug(self.application_name)

        if ":" in str(self.application_name):
            app_name = str(self.application_name).split(":")[0]
        else:
            app_name = self.application_name

        for ctx in sq.applicationContextList():
            if app_name in ctx.name and ctx.isRunning:
                this_ctx = ctx
                break

        if not this_ctx: return False
        import miscellaneous
        if this_ctx.host.startswith("localhost") or this_ctx.host.startswith("127.0.0."):
            logger.debug("LOCAL call to show_application_by_pid(), host: " + str(this_ctx.host) + ", pid:" + str(this_ctx.pid))
            miscellaneous.show_application_by_pid(this_ctx.pid)
        else:
            logger.debug("REMOTE call to show_application_by_pid(), host: " + str(this_ctx.host) + ", pid:" + str(this_ctx.pid))
            miscellaneous.execute_remote_py_function(miscellaneous.show_application_by_pid, [this_ctx.pid])

